import { expect, test } from '@playwright/test';

// Baselines are OS/font-rendering-sensitive — generated by CI (ubuntu-latest), not locally.
// First run against a new/changed page fails with "no baseline found": run with
// `--update-snapshots` in CI, review the diff, then commit the generated PNGs.
const pages = [
  { path: '/', name: 'home' },
  { path: '/reports', name: 'reports' },
  { path: '/sign-in', name: 'sign-in' },
];

for (const { path, name } of pages) {
  test(`${name} page matches visual baseline`, async ({ page }) => {
    await page.goto(path);
    await expect(page).toHaveScreenshot(`${name}.png`, { fullPage: true });
  });
}
